// Advisory model changes check order only. All rejects have exact final-state witnesses.
const TAIL:usize=96;
type PointTriple=((U256,U256),(U256,U256),(U256,U256));
struct Packet{keys:Vec<u8>,next:usize,batches:Vec<Vec<PointTriple>>}
impl Packet{
 fn ensure(&mut self,batch:usize,curve:&FastCurveC)->bool{while self.batches.len()<=batch{let mut pts=Vec::with_capacity(64);while pts.len()<64&&self.next<NUM_TESTS{let count=(64-pts.len()).min(NUM_TESTS-self.next);let mut scalars=Vec::with_capacity(count*2);for i in self.next..self.next+count{let off=i*64;scalars.push(U256::from_le_slice(&self.keys[off..off+32]));scalars.push(U256::from_le_slice(&self.keys[off+32..off+64]));}self.next+=count;for(t,o,e)in curve.points_with_sums(&scalars){if t.0!=o.0&&!(t.0.is_zero()&&t.1.is_zero())&&!(o.0.is_zero()&&o.1.is_zero()){pts.push((t,o,e));}}}if pts.is_empty(){return false;}self.batches.push(pts);}true}
}
fn nonce_tail(tail:&[Op],nonce:u64)->Vec<Op>{assert!(nonce<1<<48);let mut t=tail.to_vec();for b in 0..48{t[2*b].q_target=QubitId((nonce>>b)&1);t[2*b+1].q_target=QubitId((nonce>>b)&1);}t}
fn tail_nonce_of(tail:&[Op])->u64{(0..48).map(|b|(tail[2*b].q_target.0&1)<<b).sum()}
fn exact_batch(p:&Compact,packets:&[Packet],indices:[usize;8],active:[bool;8],regs:&[Vec<QubitOrBit>],nq:usize,nb:usize,rng:&[u64])->[&'static str;8]{
 let mut q=vec![0u64;nq*8];let mut b=vec![0u64;nb*8];let mut phase=[0u64;8];let mut stack=vec![0u64;4096*8];let mut used=0usize;
 for j in 0..8{if !active[j]{continue;}for(lane,(t,o,_))in packets[j].batches[indices[j]].iter().enumerate(){for(reg,value)in regs[..4].iter().zip([t.0,t.1,o.0,o.1]){for(i,wire)in reg.iter().enumerate(){let v=(value.bit(i)as u64)<<lane;match wire{QubitOrBit::Qubit(id)=>q[id.0 as usize*8+j]|=v,QubitOrBit::Bit(id)=>b[id.0 as usize*8+j]|=v}}}}}
 assert_eq!(unsafe{(exact_backend().run)(p.ops.as_ptr(),p.ops.len(),q.as_mut_ptr(),b.as_mut_ptr(),phase.as_mut_ptr(),rng.as_ptr(),p.rng_count,stack.as_mut_ptr(),4096,&mut used)},0);assert_eq!(used,p.rng_count);
 let mut result=["inactive";8];for j in 0..8{if !active[j]{continue;}let pts=&packets[j].batches[indices[j]];let mask=if pts.len()==64{u64::MAX}else{(1u64<<pts.len())-1};let mut classical=false;
 for(lane,(_,_,expected))in pts.iter().enumerate(){for(reg,value)in regs[..2].iter().zip([expected.0,expected.1]){for(i,wire)in reg.iter().enumerate(){let raw=match wire{QubitOrBit::Qubit(id)=>q[id.0 as usize*8+j],QubitOrBit::Bit(id)=>b[id.0 as usize*8+j]};classical|=((raw>>lane)&1)!=(value.bit(i)as u64);}}}
 for reg in regs{for wire in reg{if let QubitOrBit::Qubit(id)=wire{q[id.0 as usize*8+j]=0;}}}let ancilla=(0..nq).any(|i|q[i*8+j]&mask!=0);result[j]=if classical{"classical"}else if phase[j]&mask!=0{"phase"}else if ancilla{"ancilla"}else{"pass"};}result
}
fn group(prefix:&Compact,base:&Shake8,hash:&Shake256,tail:&[Op],nonces:[u64;8],valid:[bool;8],regs:&[Vec<QubitOrBit>],nq:usize,nb:usize,curve:&FastCurveC,model:&RailAdvisory,advisory:bool)->Vec<serde_json::Value>{
 let start=std::time::Instant::now();let mut encoded=Vec::with_capacity(TAIL*49*8);for nonce in nonces{for op in nonce_tail(tail,nonce){encoded.extend_from_slice(&record49(&op));}}let mut ctx=base.copy();ctx.different(&encoded,TAIL*49);ctx.finalize();let keys=ctx.squeeze(NUM_TESTS*64);
 for j in 0..8{let mut h=hash.clone();h.update(&encoded[j*TAIL*49..(j+1)*TAIL*49]);let mut check=[0u8;64];XofReader::read(&mut h.finalize_xof(),&mut check);assert_eq!(&check,&keys[j*NUM_TESTS*64..j*NUM_TESTS*64+64],"SHAKE8 transcript self-check");}
 let mut packets:Vec<Packet>=(0..8).map(|j|Packet{keys:keys[j*NUM_TESTS*64..(j+1)*NUM_TESTS*64].to_vec(),next:0,batches:Vec::new()}).collect();let mut indices=[0;8];let mut hits=[false;8];let no_hit=std::env::var_os("ADVISORY_NO_HIT").is_some();let prepstart=std::time::Instant::now();
 let forced=std::env::var("ADVISORY_FORCE_BATCH").ok().map(|x|x.parse::<usize>().unwrap());
 for j in 0..8{if !valid[j]{continue;}if let Some(index)=forced{if packets[j].ensure(index,curve){indices[j]=index;}}else if advisory{let mut i=0;while packets[j].ensure(i,curve){if !no_hit&&packets[j].batches[i].iter().any(|(t,o,e)|model.flags(*t,*o,*e)!=0){indices[j]=i;hits[j]=true;break;}i+=1;}}else{packets[j].ensure(0,curve);}}
 let prepsecs=prepstart.elapsed().as_secs_f64();let mut selected=ctx.copy();let rng=selected.select(indices.map(|i|i*prefix.rng_count),prefix.rng_count);let mut active=valid;for j in 0..8{active[j]&=packets[j].ensure(indices[j],curve);}let result=exact_batch(prefix,&packets,indices,active,regs,nq,nb,&rng);drop(rng);let mut kinds=["pass";8];let mut witness=[None;8];let mut batches=[0;8];let mut remaining=valid;
 for j in 0..8{if active[j]{batches[j]+=1;if result[j]!="pass"{kinds[j]=result[j];witness[j]=Some(indices[j]);remaining[j]=false;}}else{remaining[j]=false;}}
 let mut i=0;while remaining.iter().any(|x|*x){let mut check=[false;8];for j in 0..8{if !remaining[j]{continue;}if !packets[j].ensure(i,curve){remaining[j]=false;continue;}check[j]=i!=indices[j];}let rng=ctx.words(prefix.rng_count);if check.iter().any(|x|*x){let results=exact_batch(prefix,&packets,[i;8],check,regs,nq,nb,&rng);for j in 0..8{if check[j]{batches[j]+=1;if results[j]!="pass"{kinds[j]=results[j];witness[j]=Some(i);remaining[j]=false;}}}}i+=1;}
 (0..8).filter(|j|valid[*j]).map(|j|serde_json::json!({"nonce":nonces[j],"pass":witness[j].is_none(),"kind":kinds[j],"batches_run":batches[j],"exact_witness_batch":witness[j],"advisory_batch":indices[j],"advisory_hit":hits[j],"no_hit_override":no_hit,"prepared_batches":packets[j].batches.len(),"advisory":advisory,"group_prep_secs":prepsecs,"group_secs":start.elapsed().as_secs_f64(),"rejection_policy":"exact_full_state_only"})).collect()
}
fn main(){let a:Vec<_>=std::env::args().collect();assert_eq!(a.len(),7,"OPS FIRST COUNT THREADS OUT MODEL_SOURCE");let ops=load_ops(&a[1]).unwrap();let n=ops.len();let tail=ops[n-TAIL..].to_vec();for pair in tail.chunks_exact(2){assert_eq!(pair[0],pair[1]);assert_eq!(pair[0].kind,OperationType::X);assert_eq!(pair[0].c_condition.0,u64::MAX);}let own=tail_nonce_of(&tail);let(nq,nb,_,regs)=analyze_ops(ops.iter());let first=a[2].parse::<u64>().unwrap();let count=a[3].parse::<usize>().unwrap();let threads=a[4].parse::<usize>().unwrap();assert!(threads>0&&threads<=16);let advisory=std::env::var("ADVISORY_MODE").unwrap_or_default()!="off";
 let mut base=Shake8::new();let mut hash=Shake256::default();for bytes in [b"quantum_ecc-fiat-shamir-v2".as_slice(),&(n as u64).to_le_bytes()]{base.same(bytes);hash.update(bytes);}let mut encoded=Vec::with_capacity(49*32768);for op in &ops[..n-TAIL]{encoded.extend_from_slice(&record49(op));if encoded.len()>=49*32768{base.same(&encoded);hash.update(&encoded);encoded.clear();}}if !encoded.is_empty(){base.same(&encoded);hash.update(&encoded);}let p=Arc::new(Compact::compile(&ops[..n-TAIL]));let curve=Arc::new(FastCurveC::new(20));let model=Arc::new(RailAdvisory::new(&a[6]));let base=Arc::new(base);let hash=Arc::new(hash);let tail=Arc::new(tail);let regs=Arc::new(regs);let next=Arc::new(AtomicUsize::new(0));let best=Arc::new(std::sync::atomic::AtomicU64::new(u64::MAX));let out=Arc::new(Mutex::new(File::create(&a[5]).unwrap()));let started=std::time::Instant::now();let mut workers=Vec::new();
 for _ in 0..threads{let(p,curve,model,base,hash,tail,regs,next,best,out)=(p.clone(),curve.clone(),model.clone(),base.clone(),hash.clone(),tail.clone(),regs.clone(),next.clone(),best.clone(),out.clone());workers.push(std::thread::spawn(move||loop{let ix=next.fetch_add(8,Ordering::SeqCst);if ix>=count||first+ix as u64>best.load(Ordering::SeqCst){break;}let nonces=std::array::from_fn(|j|first+(ix+j).min(count-1)as u64);let valid=std::array::from_fn(|j|ix+j<count&&nonces[j]<=best.load(Ordering::SeqCst));for result in group(&p,&base,&hash,&tail,nonces,valid,&regs,nq as usize,nb as usize,&curve,&model,advisory){if result["pass"]==true{best.fetch_min(result["nonce"].as_u64().unwrap(),Ordering::SeqCst);}writeln!(out.lock().unwrap(),"{result}").unwrap();}}));}for worker in workers{worker.join().unwrap();}let b=best.load(Ordering::SeqCst);println!("ADVISORY_SCREEN_DONE own={own} first={first} count={count} best={b} wall_seconds={:.6} exact_confirmation=true",started.elapsed().as_secs_f64());if b!=u64::MAX{let mut rewritten=ops[..n-TAIL].to_vec();rewritten.extend(nonce_tail(&tail,b));let r=run_tests(&rewritten,&regs,nq,nb,fiat_shamir_seed(&rewritten),NUM_TESTS);assert!(r.ok,"selected nonce failed protected official replay");println!("SELECTED_OFFICIAL_REPLAY nonce={b} ok={} shots={} classical={} phase={} ancilla={}",r.ok,r.n_shots,r.classical_failures,r.phase_garbage_batches,r.ancilla_garbage_batches);}}

#[cfg(test)]mod acceptance_tests{
 use super::*;
 #[test]fn exact_skip_refill_partial_batch_and_input_order(){
  let c=FastCurveC::new(16);let order=U256::from_str_radix("FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141",16).unwrap();let one=U256::from(1);let zero=U256::ZERO;
  let mut pairs=vec![(zero,one),(one,zero),(order,one),(one,one),(one,order-one)];
  // 70 accepted pairs force a complete64-shot batch and a partial6-shot one.
  for i in 2..72{pairs.push((one,U256::from(i)));}pairs.resize(NUM_TESTS,(zero,zero));let mut keys=Vec::new();for(a,b)in pairs{keys.extend_from_slice(&a.to_le_bytes::<32>());keys.extend_from_slice(&b.to_le_bytes::<32>());}let mut p=Packet{keys,next:0,batches:Vec::new()};assert!(p.ensure(0,&c));assert_eq!(p.batches[0].len(),64);assert!(p.ensure(1,&c));assert_eq!(p.batches[1].len(),6);assert!(!p.ensure(2,&c));assert_eq!(p.next,NUM_TESTS);
  let curve=secp256k1();for(i,(t,o,e))in p.batches.iter().flatten().enumerate(){let a=curve.mul(curve.gx,curve.gy,one);let b=curve.mul(curve.gx,curve.gy,U256::from(i+2));assert_eq!(*t,a);assert_eq!(*o,b);assert_eq!(*e,curve.add(a.0,a.1,b.0,b.1));}
 }
}
